108→        self.mode = mode;
109→    }
110→
111→    fn show_run_header(
112→        &mut self,
113→        app_name: &str,
114→        workflow: &str,
115→        step_count: usize,
116→        version: &str,
117→    ) {
118→        if self.mode.shows_status() {
