300→        let ui = TerminalUI::new(OutputMode::Quiet);
301→        assert_eq!(ui.output_mode(), OutputMode::Quiet);
302→    }
303→
304→    #[test]
305→    fn create_ui_non_interactive() {
306→        let ui = create_ui(false, OutputMode::Normal);
307→        assert!(!ui.is_interactive());
308→    }
