import re, os

# Find all .rs files
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            lines = fh.readlines()

        in_test = False
        brace_depth = 0
        test_brace_start = 0

        for i, line in enumerate(lines):
            stripped = line.strip()

            # Track #[cfg(test)] mod blocks
            if '#[cfg(test)]' in stripped:
                in_test = True
                test_brace_start = 0
                continue

            if in_test and test_brace_start == 0:
                # Count braces to know when we exit the test module
                for ch in line:
                    if ch == '{':
                        test_brace_start += 1
                        brace_depth = 1
                        break
                continue

            if in_test and test_brace_start > 0:
                for ch in line:
                    if ch == '{':
                        brace_depth += 1
                    elif ch == '}':
                        brace_depth -= 1
                        if brace_depth == 0:
                            in_test = False
                            break

            if not in_test and '.unwrap()' in line:
                print(f'{path}:{i+1}: {line.rstrip()}')
"

