290→                        }
291→                    }
292→
293→                    term.show_cursor()?;
294→                    term.flush()?;
295→
296→                    return Ok(Some(sel));
297→                }
298→                _ => {}
299→            }
300→
301→            paging.update(sel)?;
302→
303→            if paging.active {
304→                render.clear()?;
305→            } else {
306→                render.clear_preserve_prompt(&size_vec)?;
307→            }
308→        }
309→    }
