/// Check if an IO error represents an EOF condition (e.g., Ctrl+D).
fn is_eof_error(err: &std::io::Error) -> bool {
    matches!(
        err.kind(),
        std::io::ErrorKind::UnexpectedEof | std::io::ErrorKind::BrokenPipe
    )
}

/// Convert dialoguer errors to BivvyError, treating EOF as user cancellation.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    let io_err: std::io::Error = e.into();
    if is_eof_error(&io_err) {
        BivvyError::UserCancelled
    } else {
        BivvyError::Io(io_err)
    }
}

