101→fn prompt_select(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
102→    // Use custom yes/no prompt for y/n keyboard shortcut support
103→    if is_yes_no(options) {
104→        return prompt_yes_no(prompt, options, term);
105→    }
106→
107→    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
108→
109→    let default_idx = prompt
110→        .default
111→        .as_ref()
112→        .and_then(|d| options.iter().position(|o| o.value == *d))
113→        .unwrap_or(0);
114→
115→    let selection = Select::with_theme(&select_theme())
116→        .with_prompt(&prompt.question)
117→        .items(&labels)
118→        .default(default_idx)
119→        .interact_on(term)
120→        .map_err(map_dialoguer_err)?;
121→
122→    Ok(PromptResult::String(options[selection].value.clone()))
123→}
