125→/// Custom yes/no prompt with `›`/`·` indicators and `y`/`n` keyboard shortcuts.
126→///
127→/// Renders options below the prompt question, indented to align with
128→/// the step name. Supports arrow keys, j/k, Enter/Space, and y/n.
129→fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
130→    let default_idx = prompt
131→        .default
132→        .as_ref()
133→        .and_then(|d| options.iter().position(|o| o.value == *d))
134→        .unwrap_or(0);
135→
136→    let mut sel = default_idx;
137→
138→    // Calculate indent: measure the visible width of the question text
139→    // to find where `[n/t] ` ends. We use a heuristic: find the first `]`
140→    // and add 2 for `] `.
141→    let indent = measure_text_width(&prompt.question)
142→        .min(prompt.question.find(']').map(|i| i + 2).unwrap_or(6));
143→    let pad = " ".repeat(indent);
144→
145→    let active_prefix = Style::new().bold();
146→    let active_style = Style::new().bold();
147→    let inactive_prefix = Style::new().dim();
148→    let inactive_style = Style::new().dim();
149→
150→    // Write prompt question
151→    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
152→    term.hide_cursor().map_err(BivvyError::Io)?;
153→
154→    let result = prompt_yes_no_loop(
155→        term,
156→        options,
157→        &mut sel,
158→        &pad,
159→        &active_prefix,
160→        &active_style,
161→        &inactive_prefix,
162→        &inactive_style,
163→        prompt,
164→    );
165→
166→    // Always restore cursor, even on error
167→    term.show_cursor().ok();
168→
169→    result
170→}
171→
172→/// Inner loop for yes/no prompt, separated to ensure cursor cleanup.
173→fn prompt_yes_no_loop(
174→    term: &Term,
175→    options: &[PromptOption],
176→    sel: &mut usize,
177→    pad: &str,
178→    active_prefix: &Style,
179→    active_style: &Style,
180→    inactive_prefix: &Style,
181→    inactive_style: &Style,
182→    prompt: &Prompt,
183→) -> Result<PromptResult> {
184→    loop {
185→        // Draw option lines
186→        for (i, opt) in options.iter().enumerate() {
187→            let line = if i == *sel {
188→                format!(
189→                    "{}{} {}",
190→                    pad,
191→                    active_prefix.apply_to("›"),
192→                    active_style.apply_to(&opt.label)
193→                )
194→            } else {
195→                format!(
196→                    "{}{} {}",
197→                    pad,
198→                    inactive_prefix.apply_to("·"),
199→                    inactive_style.apply_to(&opt.label)
200→                )
201→            };
202→            term.write_line(&line).map_err(BivvyError::Io)?;
203→        }
204→        term.flush().map_err(BivvyError::Io)?;
205→
206→        // Read key, treating EOF as user cancellation
207→        let key = match term.read_key() {
208→            Ok(k) => k,
209→            Err(e) if is_eof_error(&e) => return Err(BivvyError::UserCancelled),
210→            Err(e) => return Err(BivvyError::Io(e)),
211→        };
212→
213→        let chosen = match key {
214→            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
215→            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
216→            // Ctrl+D: treat as user cancellation
217→            Key::Char('\x04') => return Err(BivvyError::UserCancelled),
218→            Key::Enter | Key::Char(' ') => Some(*sel),
219→            Key::ArrowDown | Key::Tab | Key::Char('j') => {
220→                *sel = (*sel + 1) % options.len();
221→                None
222→            }
223→            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
224→                *sel = (*sel + options.len() - 1) % options.len();
225→                None
226→            }
227→            _ => None,
228→        };
229→
230→        if let Some(idx) = chosen {
231→            // Clear option lines
232→            term.clear_last_lines(options.len())
233→                .map_err(BivvyError::Io)?;
234→            // Clear the prompt question line
235→            term.clear_last_lines(1).map_err(BivvyError::Io)?;
236→            // Re-print prompt with selection (show "yes" or "no")
237→            let answer_text = if options[idx].value == "yes" {
238→                "yes"
239→            } else {
240→                "no"
241→            };
242→            term.write_line(&format!(
243→                "{} {}",
244→                prompt.question,
245→                Style::new().bold().apply_to(answer_text)
246→            ))
247→            .map_err(BivvyError::Io)?;
248→
249→            return Ok(PromptResult::String(options[idx].value.clone()));
250→        }
251→
252→        // Clear option lines for redraw
253→        term.clear_last_lines(options.len())
254→            .map_err(BivvyError::Io)?;
255→    }
256→}
257→
258→fn prompt_multiselect(
259→    prompt: &Prompt,
260→    options: &[PromptOption],
261→    term: &Term,
262→) -> Result<PromptResult> {
263→    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
264→
265→    let default_values: Vec<&str> = prompt
266→        .default
267→        .as_deref()
268→        .map(|d| d.split(',').collect())
269→        .unwrap_or_default();
270→    let defaults: Vec<bool> = options
271→        .iter()
272→        .map(|o| default_values.contains(&o.value.as_str()))
273→        .collect();
274→
275→    let selections = MultiSelect::with_theme(&prompt_theme())
276→        .with_prompt(&prompt.question)
277→        .items(&labels)
278→        .defaults(&defaults)
279→        .interact_on(term)
280→        .map_err(map_dialoguer_err)?;
281→
282→    let values: Vec<String> = selections
283→        .iter()
284→        .map(|&i| options[i].value.clone())
285→        .collect();
286→
287→    Ok(PromptResult::Strings(values))
288→}
