}

/// Inner loop for yes/no prompt, separated to ensure cursor cleanup.
fn prompt_yes_no_loop(
    term: &Term,
    options: &[PromptOption],
    sel: &mut usize,
    prompt: &Prompt,
    render_line: impl Fn(usize) -> String,
) -> Result<PromptResult> {
    loop {
        // Draw option lines
        for i in 0..options.len() {
            term.write_line(&render_line(i))
                .map_err(BivvyError::Io)?;
        }
        term.flush().map_err(BivvyError::Io)?;

        // Read key, treating EOF as user cancellation
        let key = match term.read_key() {
            Ok(k) => k,
            Err(e) if is_eof_error(&e) => return Err(BivvyError::UserCancelled),
            Err(e) => return Err(BivvyError::Io(e)),
        };

        let chosen = match key {
            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
